CREATE TABLE categorie_cours (id INT AUTO_INCREMENT NOT NULL, titre VARCHAR(255) NOT NULL, description LONGTEXT NOT NULL, niveau VARCHAR(255) NOT NULL, datepublication DATETIME NOT NULL, PRIMARY KEY (id)) DEFAULT CHARACTER SET utf8mb4;
CREATE TABLE book (id INT AUTO_INCREMENT NOT NULL, titre VARCHAR(255) NOT NULL, author VARCHAR(255) NOT NULL, description VARCHAR(255) NOT NULL, publier DATE NOT NULL, PRIMARY KEY (id)) DEFAULT CHARACTER SET utf8mb4;
CREATE TABLE offrestage (id INT AUTO_INCREMENT NOT NULL, titre VARCHAR(255) NOT NULL, description LONGTEXT NOT NULL, entreprise VARCHAR(255) NOT NULL, lieu VARCHAR(255) NOT NULL, domaine VARCHAR(255) NOT NULL, competences LONGTEXT NOT NULL, duree INT NOT NULL, date_publication DATETIME NOT NULL, statut VARCHAR(255) DEFAULT NULL, PRIMARY KEY (id)) DEFAULT CHARACTER SET utf8mb4;
CREATE TABLE stagecondidature (id INT AUTO_INCREMENT NOT NULL, type_request VARCHAR(255) NOT NULL, titre VARCHAR(255) NOT NULL, description LONGTEXT NOT NULL, domaine VARCHAR(255) NOT NULL, competences LONGTEXT NOT NULL, cv VARCHAR(255) NOT NULL, lettre_motivation LONGTEXT NOT NULL, date_publication DATE NOT NULL, statut VARCHAR(255) NOT NULL, id_etudiant INT NOT NULL, id_offre INT NOT NULL, PRIMARY KEY (id)) DEFAULT CHARACTER SET utf8mb4;
CREATE TABLE project (id INT AUTO_INCREMENT NOT NULL, title VARCHAR(255) NOT NULL, description LONGTEXT NOT NULL, status VARCHAR(50) NOT NULL, start_date DATE NOT NULL, end_date DATE DEFAULT NULL, created_at DATETIME NOT NULL, updated_at DATETIME DEFAULT NULL, PRIMARY KEY (id)) DEFAULT CHARACTER SET utf8mb4;
CREATE TABLE quiz (id INT AUTO_INCREMENT NOT NULL, title VARCHAR(255) NOT NULL, description LONGTEXT DEFAULT NULL, duration INT NOT NULL, difficulty VARCHAR(50) NOT NULL, created_at DATETIME NOT NULL, PRIMARY KEY (id)) DEFAULT CHARACTER SET utf8mb4;
CREATE TABLE book_categorie (id INT AUTO_INCREMENT NOT NULL, titre VARCHAR(255) NOT NULL, description VARCHAR(255) NOT NULL, date DATE NOT NULL, status VARCHAR(20) DEFAULT 'active' NOT NULL, PRIMARY KEY (id)) DEFAULT CHARACTER SET utf8mb4;
CREATE TABLE cours_categorie (id INT AUTO_INCREMENT NOT NULL, nom VARCHAR(255) NOT NULL, description LONGTEXT NOT NULL, slug VARCHAR(255) NOT NULL, datecreation DATETIME NOT NULL, PRIMARY KEY (id)) DEFAULT CHARACTER SET utf8mb4;
CREATE TABLE cours (id INT AUTO_INCREMENT NOT NULL, nom VARCHAR(255) NOT NULL, description LONGTEXT NOT NULL, slug VARCHAR(255) NOT NULL, type_media VARCHAR(50) NOT NULL, media_url VARCHAR(500) NOT NULL, duree INT NOT NULL, niveau VARCHAR(50) NOT NULL, date_creation DATETIME NOT NULL, enseignant VARCHAR(255) NOT NULL, categorie_cours_id INT NOT NULL, INDEX IDX_FDCA8C9C464839DA (categorie_cours_id), PRIMARY KEY (id)) DEFAULT CHARACTER SET utf8mb4;
CREATE TABLE formulaire (id INT AUTO_INCREMENT NOT NULL, titre VARCHAR(255) NOT NULL, description VARCHAR(255) NOT NULL, temps_limite INT DEFAULT NULL, category VARCHAR(255) NOT NULL, PRIMARY KEY (id)) DEFAULT CHARACTER SET utf8mb4;
CREATE TABLE question (id INT AUTO_INCREMENT NOT NULL, question_text VARCHAR(255) NOT NULL, type VARCHAR(255) NOT NULL, correct_answer VARCHAR(255) NOT NULL, points INT NOT NULL, formulaire_id INT NOT NULL, INDEX IDX_B6F7494E5053569B (formulaire_id), PRIMARY KEY (id)) DEFAULT CHARACTER SET utf8mb4;
CREATE TABLE depots (id INT AUTO_INCREMENT NOT NULL, title VARCHAR(255) NOT NULL, description LONGTEXT DEFAULT NULL, type VARCHAR(50) NOT NULL, file_path VARCHAR(255) NOT NULL, file_size VARCHAR(50) DEFAULT NULL, file_type VARCHAR(100) DEFAULT NULL, uploaded_at DATETIME NOT NULL, student_name VARCHAR(100) NOT NULL, download_count INT DEFAULT 0 NOT NULL, project_id INT NOT NULL, INDEX IDX_D99EA427166D1F9C (project_id), PRIMARY KEY (id)) DEFAULT CHARACTER SET utf8mb4;
CREATE TABLE messenger_messages (id BIGINT AUTO_INCREMENT NOT NULL, body LONGTEXT NOT NULL, headers LONGTEXT NOT NULL, queue_name VARCHAR(190) NOT NULL, created_at DATETIME NOT NULL, available_at DATETIME NOT NULL, delivered_at DATETIME DEFAULT NULL, INDEX IDX_75EA56E0FB7336F0E3BD61CE16BA31DBBF396750 (queue_name, available_at, delivered_at, id), PRIMARY KEY (id)) DEFAULT CHARACTER SET utf8mb4;
ALTER TABLE cours ADD CONSTRAINT FK_FDCA8C9C464839DA FOREIGN KEY (categorie_cours_id) REFERENCES categorie_cours (id);
ALTER TABLE question ADD CONSTRAINT FK_B6F7494E5053569B FOREIGN KEY (formulaire_id) REFERENCES formulaire (id);
ALTER TABLE depots ADD CONSTRAINT FK_D99EA427166D1F9C FOREIGN KEY (project_id) REFERENCES project (id) ON DELETE CASCADE;
